import React, { useState, useEffect } from 'react';
import { useTable, useSortBy, useFilters } from 'react-table';
import 'react-datepicker/dist/react-datepicker.css';
import '../styles/List.css';
import { RESERVATIONS_URL } from '../config';
import { useLocation } from './AreaContext';

const List = ({ filter }) => {
  const [data, setData] = useState([]);
  const { selectedLocation } = useLocation();
  

  const fetchData = () => {
    fetch(`${RESERVATIONS_URL}${selectedLocation}.json`)
      .then((response) => response.json())
      .then((data) => {
        // Process data to combine airspaces and determine altitudes
        const processedData = data.map((reservation) => {
          const callsigns = reservation.callsigns.map((callsign) => callsign).join(', ');
          const airspaces = reservation.areas.map((area) => area.area_id).join(', ');
          const lower = Math.min(...reservation.areas.map((area) => area.lower));
          const upper = Math.max(...reservation.areas.map((area) => area.upper));
          const isAltitudesDifferent = reservation.areas.some(
            (area) => area.lower !== lower || area.upper !== upper
          );
          return { ...reservation, callsigns, airspaces, lower, upper, isAltitudesDifferent };
        });
        setData(processedData);
      })
      .catch((error) => {
        console.error('Error loading or processing JSON data:', error);
      });
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(() => {
      fetchData();
    }, 60000); // Update every minute

    return () => clearInterval(interval); // Cleanup interval on component unmount
  }, []);

  const columns = React.useMemo(
    () => [
      { Header: 'Creator', accessor: 'creator' },
      { Header: 'Start Date', accessor: 'start' },
      { Header: 'End Date', accessor: 'end' },
      { Header: 'Status', accessor: 'status' },
      { Header: 'Airspace', accessor: 'airspaces' },
      { Header: 'Lower', accessor: 'lower' },
      { Header: 'Upper', accessor: 'upper' },
      { Header: 'Callsigns', accessor: 'callsigns' },
    ],
    []
  );

  const {
    getTableProps,
    getTableBodyProps,
    headerGroups,
    rows,
    prepareRow,
    setFilter,
  } = useTable(
    {
      columns,
      data,
    },
    useFilters,
    useSortBy
  );
  
  useEffect(() => {
    setFilter('airspaces', filter || '');
  }, [filter, setFilter]);

  // Function to format dates into UTC format: DD/MM/YYYY HH:mm
  const formatDate = (timestamp) => {
    const date = new Date(timestamp);
    const day = String(date.getUTCDate()).padStart(2, '0');
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const year = date.getUTCFullYear();
    const hours = String(date.getUTCHours()).padStart(2, '0');
    const minutes = String(date.getUTCMinutes()).padStart(2, '0');
    return `${day}/${month}/${year} ${hours}:${minutes}`;
  };

  // Function to get background color based on status
  const getRowBackgroundColor = (status) => {
    switch (status) {
      case 'pending':
        return '#ea9750';
      case 'active':
        return '#40bb78';
      case 'cancelled':
        return '#ea5056';
      default:
        return 'transparent';
    }
  };

  return (
    <div className="list-container">
      
      {/* Table */}
      <table className="list-table" {...getTableProps()}>
        <thead>
          {headerGroups.map((headerGroup) => {
            const { key: headerKey, ...headerRest } = headerGroup.getHeaderGroupProps();
            return (
              <tr key={headerKey} {...headerRest}>
                {headerGroup.headers.map((column) => {
                  const { key: colKey, ...colRest } = column.getHeaderProps(column.getSortByToggleProps());
                  return (
                    <th
                      key={colKey}  // key directly
                      {...colRest}   // spread remaining props
                      style={{ cursor: 'pointer', userSelect: 'none' }}
                    >
                      {column.render('Header')}
                      {column.isSorted ? (column.isSortedDesc ? ' ▼' : ' ▲') : ''}
                    </th>
                  );
                })}
              </tr>
            );
          })}
        </thead>
        <tbody {...getTableBodyProps()}>
          {rows.length > 0 ? (
            rows.map((row, rowIndex) => {
              prepareRow(row);
              const { key: rowKey, ...rowRest } = row.getRowProps();
              return (
                <tr
                  key={rowKey}  // key directly
                  {...rowRest}
                  style={{
                    backgroundColor: rowIndex % 2 === 0 ? '#f9f9f9' : '#e9e9e9',
                  }}
                >
                  {row.cells.map((cell) => {
                    const { key: cellKey, ...cellRest } = cell.getCellProps();

                    let content;
                    if (cell.column.id === 'start' || cell.column.id === 'end') {
                      content = formatDate(cell.value);
                    } else if (cell.column.id === 'lower' || cell.column.id === 'upper') {
                      const isAltitudesDifferent = row.original.isAltitudesDifferent;
                      const value = cell.value === 0 ? 'SFC' : cell.value === 999 ? 'UNL' : cell.value;
                      content = value;
                      return (
                        <td key={cellKey} {...cellRest} style={{ color: isAltitudesDifferent ? 'orange' : 'black' }}>
                          {content}
                        </td>
                      );
                    } else if (cell.column.id === 'status') {
                      content = cell.render('Cell');
                      return (
                        <td key={cellKey} {...cellRest} style={{ backgroundColor: getRowBackgroundColor(cell.value) }}>
                          {content}
                        </td>
                      );
                    } else {
                      content = cell.render('Cell');
                    }

                    return <td key={cellKey} {...cellRest}>{content}</td>;
                  })}
                </tr>
                );
              })
            ) : (
            <tr>
              <td colSpan="8" style={{ textAlign: 'center', color: '#888' }}>
                No reservations found
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default List;
